/**
 * noteDeDepart.js — LA NOTE DE DÉPART du moteur, écrite dans le code (étape 19 du plan, 13/10/2026).
 * -----------------------------------------------------------------------
 * L'état du moteur à la fin de l'étape 19, et ses chiffres au banc d'essai.
 * Dans le CODE, comme lancements.js et historique.js : les données
 * d'exécution du bac ne sont jamais recopiées chez Pierre, le code l'est.
 * L'étape 47 la relit : non pas un chiffre à battre dans l'absolu (une perte
 * log dépend de la fenêtre), mais un moteur REJOUABLE — son empreinte (code +
 * réglages, engineVersions.js) et le commit du dépôt qui porte ce code —,
 * rejoué face au moteur final sur les MÊMES matchs d'après le lancement.
 *
 * Ce qu'elle contient :
 *   - moteur        l'identité du moteur (empreintes, réglages ; le commit est
 *                   celui de la recopie qui porte ce code : il n'existe pas
 *                   encore quand le bac rejoue, il se note à la recopie) ;
 *   - reproduction  la référence du 23/09 retrouvée (P4b, moyenne de clôture)
 *                   — l'étalonnage du banc, PAS une note ;
 *   - depart        les notes avant-match, marché par marché, sur P4b (déjà
 *                   vue : comparable à FIABILITE) et P2 (jamais vue : preuve
 *                   au banc), et les paris simulés de P2 ;
 *   - rejeu         le rejeu du bac d'où les chiffres sont RECOPIÉS
 *                   (noteDepuisUnRejeu, jamais retapés).
 * Ce qu'elle n'est pas : une preuve neuve (P4b est vue, P2 est une preuve au
 * banc). Chez Pierre, la reproduction se retrouve à 1e-3 et ± 1 % de
 * rencontres ; l'égalité exacte vaut pour la copie du bac datée ici.
 * Pure : ne lit rien.
 * -----------------------------------------------------------------------
 */

/**
 * LE COMMIT du dépôt qui porte le moteur de départ (empreinte du code 6ed7e010…, version 3 chez Pierre) : 2e602ea,
 * le dernier des cinq commits du 20/10/2026 (tout ce qui était en service depuis le 03/10, envoyés sur GitHub à la
 * demande de Pierre). Vérifié : empreinteDuCode sur le contenu de ce commit (git archive) rend 6ed7e010f507…, celle de
 * la note. La note elle-même entre dans un commit suivant. Si ce commit manquait (null), l'étape 47 refuserait de
 * rejouer « le moteur de départ » depuis git (exigerLeCommitDeDepart) et le dirait ; les chiffres de la note, eux,
 * resteraient justes.
 */
export const COMMIT_DU_MOTEUR_DE_DEPART = '2e602ea69ce5a905fbdee6d09c89d86ea626c137';

/** Ce que la note dit tant que le commit manque (aussi à l'écran). */
export const COMMIT_MANQUANT =
  'Aucun commit du dépôt ne porte encore ce moteur (le dépôt n’a pas été commité depuis le 03/10 : c’est la décision de Pierre). Ses chiffres sont justes et son empreinte est notée, mais l’étape 47 ne pourra le rejouer depuis git qu’une fois le commit fait et son identifiant écrit dans noteDeDepart.js.';

/** Le moteur de départ ne se rejoue pas sans son commit (étape 47). */
export class MoteurDeDepartSansCommit extends Error {}

/**
 * LA GARDE de l'étape 47 : rejouer « le moteur de départ » (git worktree au commit de la note, puis le banc) exige
 * son commit. Rend { commit, empreinte, empreinteCode } ; lève MoteurDeDepartSansCommit, qui dit quoi faire, sinon.
 */
export function exigerLeCommitDeDepart(note = NOTE_DE_DEPART) {
  const commit = note?.moteur?.commit ?? null;
  if (typeof commit !== 'string' || !/^[0-9a-f]{40}$/.test(commit)) {
    throw new MoteurDeDepartSansCommit(
      'Le moteur de départ ne se rejoue pas : la note de départ n’a pas de commit (aucun commit du dépôt ne porte ce moteur). Il faut d’abord que le dépôt soit commité, puis écrire l’identifiant du commit (git rev-parse HEAD) dans noteDeDepart.js, COMMIT_DU_MOTEUR_DE_DEPART.'
    );
  }
  return { commit, empreinte: note.moteur.empreinte ?? null, empreinteCode: note.moteur.empreinteCode ?? null };
}

const p4 = (x) => (typeof x === 'number' && Number.isFinite(x) ? Number(x.toFixed(4)) : null);
const p2 = (x) => (typeof x === 'number' && Number.isFinite(x) ? Number(x.toFixed(2)) : null);

/** Le résumé d'une case pour la note : n, le moteur, le marché et le repère avec le verdict du juge. */
function caseDeLaNote(c) {
  const duel = (x) =>
    x
      ? {
          n: x.n,
          perteLog: p4(x.perteLog),
          moteurPerteLog: p4(x.moteurPerteLog),
          gain: p4(x.juge?.gain),
          fourchette: x.juge?.fourchette ? x.juge.fourchette.map(p4) : null,
          enPourcent: x.juge?.enPourcent ? { gain: p2(x.juge.enPourcent.gain), fourchette: x.juge.enPourcent.fourchette?.map(p2) ?? null } : null,
          verdict: x.juge?.verdict ?? null
        }
      : null;
  return {
    n: c.n,
    moteur: { perteLog: p4(c.moteur.perteLog), brier: p4(c.moteur.brier), rps: p4(c.moteur.rps), justes: c.moteur.justes ? p2(c.moteur.justes.taux) : null, top3: c.moteur.top3 ? p2(c.moteur.top3.taux) : null },
    marche: duel(c.marche),
    repere: duel(c.repere),
    unUnPartout: c.repere?.un11 ? p2(c.repere.un11.taux) : null,
    calibration: c.calibration ? c.calibration.tranches.map((t) => ({ de: t.de, a: t.a, n: t.n, annonce: p4(t.annonce), realise: p4(t.realise) })) : null
  };
}

/** Les notes d'une tranche × jeu de prix : une par ligne de marché (sous-table « tout »). */
function notesDUneTranche(resume, tranche, prix) {
  const cases = resume?.tranches?.[tranche]?.cases ?? [];
  const out = {};
  for (const c of cases) {
    if (c.prix !== prix || c.sousTable !== 'tout') continue;
    out[`${c.marketKey}${c.ligne === null || c.ligne === undefined ? '' : `|${c.ligne}`}`] = caseDeLaNote(c);
  }
  return out;
}

/**
 * Les fenêtres DÉJÀ VUES d'une tranche × jeu de prix, recopiées des cases du résumé (leurs vues.parFenetre ; sous-table
 * « tout »), jamais retapées (correction du 19/10) : la note dira juste le jour où une fenêtre de portée « moteur »
 * couvrira P2 (étape 27).
 */
function vuesDUneTranche(resume, tranche, prix) {
  const ids = new Set();
  for (const c of resume?.tranches?.[tranche]?.cases ?? []) {
    if (c.prix !== prix || c.sousTable !== 'tout') continue;
    for (const [id, n] of Object.entries(c.vues?.parFenetre ?? {})) if (n > 0) ids.add(id);
  }
  return [...ids].sort();
}

/** Les paris d'une tranche (règle du moteur) pour la note. */
function parisDeLaNote(resume, tranche, prix = 'fd-avant-match') {
  const p = (resume?.paris ?? []).find((x) => x.tranche === tranche && x.prix === prix && x.regle === 'moteur');
  if (!p) return null;
  return {
    regle: 'moteur',
    decisions: p.decisions,
    paris: p.n,
    refus: p.refus,
    rendement: { parUnite: p4(p.rendement?.parUnite), fourchette: p.rendement?.juge?.fourchette?.map(p4) ?? null, ecartDetectable: p4(p.rendement?.juge?.ecartDetectable), rapporteSeulement: true },
    valeurCloture: { n: p.valeurCloture?.n ?? 0, moyenne: p4(p.valeurCloture?.moyenne), fourchette: p.valeurCloture?.juge?.fourchette?.map(p4) ?? null, verdict: p.valeurCloture?.juge?.verdict ?? null },
    pireSerie: p.pireSerie,
    zoneNormale: p.zoneNormale
  };
}

/**
 * La note de départ tirée d'un rejeu fini de bench_runs (lireRejeu) : les chiffres RECOPIÉS de son résumé,
 * jamais retapés. `identite` : ce que le rejeu ne sait pas de lui-même (date du calcul, fichier de la base,
 * commit). Pure.
 */
export function noteDepuisUnRejeu(rejeu, identite = {}) {
  const r = rejeu.resume;
  const rp = r.reproduction;
  return {
    format: 1,
    calculeeLe: identite.calculeeLe ?? rejeu.finiLe?.slice(0, 10) ?? null,
    ou: 'bac à sable',
    rejeu: {
      id: rejeu.id,
      dureeMs: rejeu.bilan?.dureeMs ?? null,
      versionBanc: rejeu.versionBanc,
      formatLignes: rejeu.formatLignes,
      graine: r.juge?.graine ?? null,
      tirages: r.juge?.tirages ?? null,
      variantes: r.juge?.variantes ?? null,
      base: identite.base ?? null,
      fdHistory: identite.fdHistory ?? null,
      tableJourJ: identite.tableJourJ ?? null
    },
    moteur: {
      empreinte: rejeu.moteur.empreinte,
      empreinteCode: rejeu.moteur.empreinteCode,
      empreinteReglages: rejeu.options?.config?.empreinte ?? null,
      version: rejeu.moteur.version ?? null,
      commit: identite.commit ?? null,
      reglages: rejeu.options?.config?.reglages ?? null
    },
    reproduction: rp
      ? {
          periode: rp.periode,
          prix: rp.prix,
          lectureDirecte: {
            matchs: rp.lectureDirecte.matchs,
            justes: p2(rp.lectureDirecte.justes),
            perteLog: p4(rp.lectureDirecte.perteLog),
            brier: p4(rp.lectureDirecte.brier),
            rps: p4(rp.lectureDirecte.rps),
            anomalies: rp.lectureDirecte.anomalies,
            tranches: rp.lectureDirecte.tranches.map((t) => t.n)
          },
          moteur: { matchs: rp.moteur.matchs, cotesIncoherentes: rp.moteur.cotesIncoherentes, justes: p2(rp.moteur.justes), perteLog: p4(rp.moteur.perteLog), brier: p4(rp.moteur.brier), rps: p4(rp.moteur.rps), maxEcartP: rp.moteur.maxEcartP },
          attribuees: rp.attribuees,
          prolongees: rp.prolongees,
          attendu: rp.attendu,
          tolerance: rp.tolerance
        }
      : null,
    depart: {
      P4b: {
        prix: 'fd-avant-match',
        vues: vuesDUneTranche(r, 'P4b', 'fd-avant-match'),
        marches: notesDUneTranche(r, 'P4b', 'fd-avant-match'),
        paris: null,
        pourquoiPasDeParis: 'Aucune cote William Hill après le 27/03/2025 et Pinnacle jusqu’au 15/01/2026 seulement : la règle du moteur n’a presque plus de prix pour parier en 2025-26 (les décisions et refus sont au résumé du rejeu).'
      },
      P2: {
        prix: 'fd-avant-match',
        vues: vuesDUneTranche(r, 'P2', 'fd-avant-match'),
        marches: notesDUneTranche(r, 'P2', 'fd-avant-match'),
        paris: parisDeLaNote(r, 'P2')
      }
    }
  };
}

/** Gèle un objet et tout ce qu'il contient : la note ne se modifie pas en mémoire. */
const gele = (o) => {
  if (o && typeof o === 'object' && !Object.isFrozen(o)) {
    Object.freeze(o);
    for (const v of Object.values(o)) gele(v);
  }
  return o;
};

